INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(117929, 'ruRU', '', 'Потренируйся использовать Телепортацию.', 24330),
(117930, 'ruRU', '', 'Телепортация позволяет переместиться на короткое расстояние, чтобы избежать опасности или приблизиться к врагу.', 24330),
(117931, 'ruRU', '', 'Но использовать свои ноги так приземлённо! К счастью, у тебя есть заклинание, достойное мастера магических искусств.', 24330),
(117932, 'ruRU', '', 'Поле боя может быть опасным местом, так что передвижение жизненно важно для твоего выживания.', 24330),
(117933, 'ruRU', '', 'Твой Элементаль воды погиб. Используй Призыв элементаля воды, чтобы призвать его снова!', 24330),
(117934, 'ruRU', '', 'Используй Невидимость!', 24330),
(117935, 'ruRU', '', 'Подожди, пока у тебя будет Хватка мороза или твоя цель будет заморожена, чтобы использовать Клинок льда.', 24330),
(117936, 'ruRU', '', 'Твоя цель заморожена! Используй Клинок льда!', 24330),
(117937, 'ruRU', '', 'Используй Клинок льда!', 24330),
(117938, 'ruRU', '', 'Сработала Хватка мороза! Используй Клинок льда прямо сейчас!', 24330),
(117939, 'ruRU', '', 'Используй Ледяную преграду!', 24330),
(117940, 'ruRU', '', 'Используй Ледяную сферу!', 24330),
(117941, 'ruRU', '', 'Ледяная сфера доступна! Используй её сейчас!', 24330),
(117942, 'ruRU', '', 'Используй Ледяную стрелу!', 24330),
(117943, 'ruRU', '', 'Используй Ледяную вспышку!', 24330),
(117944, 'ruRU', '', 'Тебе нужно заморозить врага на месте, прежде чем он доберётся до тебя.', 24330),
(117945, 'ruRU', '', 'Используй Ледяную вспышку!', 24330),
(117946, 'ruRU', '', 'Используй Снежную бурю!', 24330),
(117947, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как маг льда.', 24330),
(117948, 'ruRU', '', 'Покажи мне необузданную силу и превосходство, которыми ты владеешь!', 24330),
(117949, 'ruRU', '', 'Используй Невидимость, чтобы выйти из боя.', 24330),
(117950, 'ruRU', '', 'Используй её, и враги не смогут выбрать тебя целью, позволяя сбежать из боя. Но будь осторожен! Эффект длится недолго.', 24330),
(117951, 'ruRU', '', 'Нужно срочно выйти из боя? Невидимость — отличное заклинание, чтобы выбраться из непростой ситуации.', 24330),
(117952, 'ruRU', '', 'Используй Ледяную преграду, чтобы снизить получаемый урон.', 24330),
(117953, 'ruRU', '', 'В таких случаях нужна дополнительная защита. Ледяная преграда создаёт щит из льда, поглощающий атаки врагов.', 24330),
(117954, 'ruRU', '', 'Несмотря на все твои усилия, тебе может не удаться помешать врагу добраться до тебя.', 24330),
(117955, 'ruRU', '', 'Используй Ледяную сферу на тренировочном манекене.', 24330),
(117956, 'ruRU', '', 'Однако будь осторожен, так как она поражает всех врагов на своём пути, а не только твою цель.', 24330),
(117957, 'ruRU', '', 'Ещё одно мощное заклинание, которым ты можешь владеть — Ледяная сфера. Используй это заклинание, когда оно доступно, так как оно может сделать твой Клинок льда мощнее.', 24330),
(117958, 'ruRU', '', 'Используй Ледяную стрелу на тренировочном манекене, пока не сработает Хватка мороза. Пока эффект активен, используй Клинок льда.', 24330),
(117959, 'ruRU', '', 'Используй Ледяную стрелу на тренировочном манекене, пока не сработает Хватка мороза. Затем используй Клинок льда.', 24330),
(117960, 'ruRU', '', 'Ледяная стрела иногда вызывает эффект Хватки мороза, что даёт огромный прирост урона Клинку льда. Давай проверим это.', 24330),
(117961, 'ruRU', '', 'Есть ещё один способ использовать Клинок льда, чтобы максимизировать его силу.', 24330),
(117962, 'ruRU', '', 'Используй Клинок льда на замороженном тренировочном манекене.', 24330),
(117963, 'ruRU', '', 'Истинная сила Клинка льда раскрывается при использовании против замороженной цели, что значительно увеличивает его урон.', 24330),
(117964, 'ruRU', '', 'Теперь посмотрим на Клинок льда. Он похож на Ледяную стрелу, но может быть использован мгновенно, хотя и с меньшим уроном.', 24330),
(117965, 'ruRU', '', 'Используй Ледяную стрелу на тренировочном манекене.', 24330),
(117966, 'ruRU', '', 'Эта дальнобойная атака наносит урон и замедляет твоих врагов, а также имеет шанс усилить другие атаки.', 24330),
(117967, 'ruRU', '', 'Твоя самая основная и надёжная атака — Ледяная стрела.', 24330),
(117968, 'ruRU', '', 'Используй Призыв элементаля воды, чтобы призвать своего питомца.', 24330);
